let state={...defaults,...stored,quest:{...defaults.quest,...(stored.quest||{})},appLabels:{...defaults.appLabels,...(stored.appLabels||{})},messages:stored.messages||defaults.messages,mail:stored.mail||defaults.mail,nodes:stored.nodes||defaults.nodes,files:stored.files||[],evidence:stored.evidence||[],calls:stored.calls||[],investigation:{...defaultInvestigation,...(stored.investigation||{}),variables:{...(stored.investigation?.variables||{})},flags:{...(stored.investigation?.flags||{})},relationships:{...(stored.investigation?.relationships||{})},inventory:[...(stored.investigation?.inventory||[])],evidence:[...(stored.investigation?.evidence||stored.evidence||[])],history:[...(stored.investigation?.history||[])]}};
let opened=new Map(),z=10,callTimer=null,studioTab="os",selectedNode=state.nodes[0]?.id||"start",runtimeNodeId=null,pendingGraphConnection=null,audioContext=null,melodyTimer=null,oscillators=[];
