const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function save(){localStorage.setItem(KEY,JSON.stringify(state));updateBadges()}
function clock(){return new Date().toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"})}
function toast(s){let n=$("#toast");n.textContent=s;n.classList.add("show");clearTimeout(toast.t);toast.t=setTimeout(()=>n.classList.remove("show"),2300)}
function notify(title,msg){updateBadges()}
function theme(t){state.theme=t;document.body.dataset.theme=t;save();$$("[data-theme-choice]").forEach(b=>b.classList.toggle("active",b.dataset.themeChoice===t))}
function unreadCount(id){if(id==="messages")return state.messages.filter(x=>x.unread).length;if(id==="mail")return state.mail.filter(x=>x.unread).length;if(id==="phone")return state.calls.filter(x=>x.unread).length;return 0}
function updateBadges(){["messages","mail","phone"].forEach(id=>{let n=unreadCount(id);$$('[data-open="'+id+'"]').forEach(b=>{let badge=b.querySelector(".app-badge");if(!badge){badge=document.createElement("span");badge.className="app-badge";b.append(badge)}badge.textContent=n>9?"9+":n;b.classList.toggle("has-badge",n>0)})})}
function samplePhoto(){let svg='<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="760" viewBox="0 0 1200 760"><defs><linearGradient id="g" x2="0" y2="1"><stop stop-color="#a9bdc5"/><stop offset="1" stop-color="#43545a"/></linearGradient><linearGradient id="f"><stop stop-color="#d4c4a8"/><stop offset="1" stop-color="#5b5148"/></linearGradient></defs><rect width="1200" height="760" fill="url(#g)"/><rect y="510" width="1200" height="250" fill="#333b3a"/><rect x="80" y="140" width="1040" height="390" fill="#77858a"/><rect x="110" y="170" width="980" height="360" fill="#9eaaa7"/><path d="M150 520V260h220v260M400 520V260h230v260M670 520V260h360v260" fill="#5b6869"/><path d="M170 285h180v220H170M420 285h190v220H420M690 285h320v220H690" fill="#b9c2bc"/><g fill="#202b31"><circle cx="855" cy="350" r="42"/><path d="M800 394q55-42 110 0l35 130H770z"/></g><path d="M876 394l25 30" stroke="#d9b36e" stroke-width="12"/><circle cx="900" cy="425" r="15" fill="none" stroke="#d9b36e" stroke-width="6"/><rect x="40" y="35" width="220" height="38" rx="5" fill="#18252b" opacity=".75"/><text x="58" y="60" fill="white" font-family="sans-serif" font-size="20">SAT · 21:14 · CAM 04</text><text x="840" y="700" fill="#fff" font-family="sans-serif" font-size="18" opacity=".7">ARCHIVE / 24-10</text></svg>';return "data:image/svg+xml;charset=utf-8,"+encodeURIComponent(svg)}
function ensureAttachment(att){let f=state.files.find(x=>x.id===att.id);if(!f){f={...att,added:clock(),data:samplePhoto(),inspected:false};state.files.push(f);save();notify("Файл получен",att.name+" сохранён в папку «Входящие»");setTimeout(()=>emitGameEvent("attachment_received",{attachment:att}),0)}return f}
state.messages.forEach(m=>{if(m.attachment)ensureAttachment(m.attachment)});
function addEvidence(title,text,source){if(state.evidence.some(e=>e.title===title))return false;state.evidence.push({title,text,source,added:clock()});if(state.quest.condition==="evidence"&&!state.quest.completed.includes("quest_condition")){state.quest.completed.push("quest_condition");state.quest.stage=2;}save();return true}
const GRAPH_EVENTS=[["game_start","Запуск игры"],["photo_inspected","Изучена фотография"],["mail_read","Прочитано письмо"],["message_sent","Отправлено сообщение"],["call_accepted","Принят звонок"],["call_declined","Отклонён звонок"],["attachment_received","Получено вложение"]];
const GRAPH_EFFECTS=[["send_message","Отправить сообщение"],["send_mail","Отправить письмо"],["incoming_call","Входящий звонок"],["add_evidence","Добавить улику"],["set_objective","Изменить цель расследования"],["open_app","Открыть приложение"],["complete_quest","Завершить квест"]];
let activeGraphRun=null,activeInspectedFileId=null;
function emitGameEvent(event,payload={}){ensureGraphData();state.nodes.filter(n=>n.type==="start"&&(n.event||"game_start")===event).forEach(root=>runGraphFrom(root.id,payload));}
function runGraphFrom(id,payload={},depth=0){if(depth>60){toast("Граф остановлен: превышен лимит переходов");return}const n=state.nodes.find(x=>x.id===id);if(!n)return;if(n.type==="end"){activeGraphRun=null;toast(n.text||"Эпизод завершён");return}if(n.type==="start"){const t=n.outputs?.find(o=>o.target)?.target;if(t)runGraphFrom(t,payload,depth+1);return}if(n.type==="dialogue"){state.messages.unshift({id:"story_"+Date.now()+"_"+Math.random().toString(36).slice(2,7),from:n.speaker||"Алексей Морозов",time:clock(),text:n.text||n.title,unread:true,story:true});save();if(opened.has("messages"))refresh("messages");toast("Новое сообщение: "+(n.speaker||"Алексей Морозов"));const t=n.outputs?.find(o=>o.target)?.target;if(t)runGraphFrom(t,payload,depth+1);return}if(n.type==="action"){executeGraphEffect(n,payload);const t=n.outputs?.find(o=>o.target)?.target;if(t)runGraphFrom(t,payload,depth+1);return}if(n.type==="condition"){const yes=evaluateGraphCondition(n.condition||"has_evidence"),t=n.outputs?.[yes?0:1]?.target;if(t)runGraphFrom(t,payload,depth+1);return}if(n.type==="choice"){showGraphChoice(n,payload,depth);return}const t=n.outputs?.find(o=>o.target)?.target;if(t)runGraphFrom(t,payload,depth+1)}
function executeGraphEffect(n,payload={}){const title=n.title||"Сюжетное событие",body=n.text||"";if(n.effect==="send_message"){state.messages.unshift({id:"story_"+Date.now(),from:n.speaker||"Алексей Морозов",time:clock(),text:body,unread:true,story:true});save();if(opened.has("messages"))refresh("messages");toast("Новое сообщение")}else if(n.effect==="send_mail"){state.mail.unshift({id:"story_mail_"+Date.now(),from:n.speaker||"Алексей Морозов",subject:title,body,unread:true,story:true});save();if(opened.has("mail"))refresh("mail");toast("Новое письмо")}else if(n.effect==="incoming_call")incoming(n.speaker||"Неизвестный номер",n.number||"+31 ••• •• ••",body||"Алло.");else if(n.effect==="add_evidence"){addEvidence(title,body,"graph");if(opened.has("case"))refresh("case");toast("Новая улика добавлена")}else if(n.effect==="set_objective"){state.quest.objective=body||title;state.quest.stage++;save();if(opened.has("case"))refresh("case");toast("Цель расследования обновлена")}else if(n.effect==="open_app"){const app=n.app||"messages";if(views[app])openApp(app)}else if(n.effect==="complete_quest"){if(!state.quest.completed.includes("graph_complete"))state.quest.completed.push("graph_complete");state.quest.stage++;state.quest.objective=body||"Задание завершено";save();if(opened.has("case"))refresh("case");toast("Квест завершён")}}
function showGraphChoice(n,payload,depth){activeGraphRun={nodeId:n.id,payload,depth};$("#story-choice")?.remove();const box=document.createElement("div");box.id="story-choice";box.className="story-choice-overlay";box.innerHTML='<section class="story-choice-card"><div class="call-kicker">ВЫБОР</div><h2>'+esc(n.title||"Твой ответ")+'</h2><p>'+esc(n.text||"Как поступить?")+'</p><div class="story-choice-options">'+(n.outputs||[]).map((o,i)=>'<button class="btn primary" data-choice-index="'+i+'">'+esc(o.label||("Вариант "+(i+1)))+"</button>").join("")+"</div></section>";$("#desktop").append(box);box.querySelectorAll("[data-choice-index]").forEach(b=>b.onclick=()=>{const i=Number(b.dataset.choiceIndex),target=n.outputs?.[i]?.target;box.remove();activeGraphRun=null;if(target)runGraphFrom(target,payload,depth+1);else toast("У выбранного ответа нет продолжения")})}
function storyEvidence(){const file=state.files.find(f=>f.id===activeInspectedFileId)||state.files.find(f=>f.id==="photo_2410");if(file)file.inspected=true;const fresh=addEvidence("Человек у служебного входа","На фотографии виден человек с часами на правой руке. Время снимка — 21:14.",file?.id||"photo");state.quest.stage=Math.max(state.quest.stage,1);save();if(fresh)notify("Новая улика","Деталь добавлена в дело №001");emitGameEvent("photo_inspected",{file})}
function markRead(id,type){let list=type==="mail"?state.mail:state.messages;let item=list.find(x=>x.id===id);if(item)item.unread=false;save()}
