 messages:()=>'<h2>Сообщения</h2><p class="subhead">Последние переписки · Локальная сеть</p>'+state.messages.map(m=>'<div class="message '+(m.unread?'unread':'')+'"><strong>'+esc(m.from)+' <span class="muted">· '+esc(m.time)+'</span></strong><p>'+esc(m.text)+'</p>'+(m.attachment?'<div class="btnrow"><button class="btn primary" data-attachment="'+esc(m.attachment.id)+'">▧ Открыть вложение · '+esc(m.attachment.name)+'</button></div>':'')+'</div>').join("")+'<div style="margin-top:17px"><input id="reply" class="field" placeholder="Написать сообщение..."><div class="btnrow"><button class="btn primary" data-action="send">Отправить</button></div></div>',
