/* Investigation State System */
function ensureInvestigation(){state.investigation=state.investigation||{variables:{},flags:{},relationships:{},inventory:[],evidence:[],history:[]};for(const k of ["variables","flags","relationships"])state.investigation[k]=state.investigation[k]||{};for(const k of ["inventory","evidence","history"])state.investigation[k]=state.investigation[k]||[]}
function recordStateChange(type,key,value){ensureInvestigation();state.investigation.history.unshift({type,key,value,at:new Date().toISOString()});state.investigation.history=state.investigation.history.slice(0,100);save()}
function setInvestigationValue(type,key,value){ensureInvestigation();key=String(key||"").trim();if(!key)return false;if(type==="variable")state.investigation.variables[key]=value;else if(type==="flag")state.investigation.flags[key]=!!value;else if(type==="relationship")state.investigation.relationships[key]=Math.max(-100,Math.min(100,Number(value)||0));else if(type==="item"){if(!state.investigation.inventory.includes(key))state.investigation.inventory.push(key)}else return false;recordStateChange(type,key,value);return true}
function changeInvestigationValue(type,key,amount){ensureInvestigation();if(type==="variable")return setInvestigationValue(type,key,(Number(state.investigation.variables[key])||0)+(Number(amount)||0));if(type==="relationship")return setInvestigationValue(type,key,(Number(state.investigation.relationships[key])||0)+(Number(amount)||0));return false}
function removeInvestigationItem(key){ensureInvestigation();let i=state.investigation.inventory.indexOf(key);if(i<0)return false;state.investigation.inventory.splice(i,1);recordStateChange("remove_item",key,false);return true}
const legacyAddEvidence=addEvidence;
addEvidence=function(title,text,source){const added=legacyAddEvidence(title,text,source);if(added){ensureInvestigation();const id=state.evidence.find(x=>x.title===title)?.id||title;if(!state.investigation.evidence.some(x=>(typeof x==="string"?x:x.id)===id||x.title===title)){state.investigation.evidence.push({id,title,description:text,added:clock()});recordStateChange("evidence",id,title)}}return added};
function tokenizeCondition(src){src=src.trim();const out=[];const re=/\s*(>=|<=|==|!=|>|<|&&|\|\||\(|\)|,|!|AND\b|OR\b|NOT\b|"(?:\\.|[^"\\])*"|\x27(?:\\.|[^\x27\\])*\x27|-?\d+(?:\.\d+)?|[A-Za-z_][A-Za-z0-9_.-]*)\s*/gy;let i=0;while(i<src.length){re.lastIndex=i;const m=re.exec(src);if(!m)throw Error("Invalid token");out.push(m[1]);i=re.lastIndex}return out}
function evaluateGraphCondition(src){ensureInvestigation();if(typeof src!=="string"||!src.trim())return false;try{const t=tokenizeCondition(src);let p=0;const peek=()=>t[p],take=()=>t[p++],truth=v=>!!v;function atom(){if(peek()==="("){take();let v=or();if(take()!==")")throw 0;return v}if(peek()==="!"||peek()==="NOT"){take();return !truth(atom())}let v=take();if(v===undefined)throw 0;if(v[0]==="\x22"||v[0]==="\x27")return v.slice(1,-1);if(/^-?\d/.test(v))return Number(v);if(v==="true"||v==="false")return v==="true";if(peek()==="("){take();let k=String(atom());if(peek()===","){take();atom()}if(take()!==")")throw 0;if(v==="flag")return !!state.investigation.flags[k];if(v==="item"||v==="has_item")return state.investigation.inventory.includes(k);if(v==="evidence"||v==="has_evidence")return state.investigation.evidence.some(x=>(typeof x==="string"?x:x.id)===k||(typeof x==="object"&&x.title===k));if(v==="rel"||v==="relationship")return Number(state.investigation.relationships[k]||0);if(v==="var"||v==="variable")return state.investigation.variables[k]??0;throw 0}if(v==="has_evidence")return state.evidence.length>0;if(v==="photo_inspected")return state.files.some(f=>f.inspected);if(v==="has_attachment")return state.files.length>0;if(v==="mail_read")return state.mail.some(m=>m.id==="mail2"&&!m.unread);if(Object.prototype.hasOwnProperty.call(state.investigation.variables,v))return state.investigation.variables[v];if(Object.prototype.hasOwnProperty.call(state.investigation.flags,v))return !!state.investigation.flags[v];if(Object.prototype.hasOwnProperty.call(state.investigation.relationships,v))return Number(state.investigation.relationships[v]||0);return false}function cmp(){let a=atom(),op=peek();if(["==","!=",">",">=","<","<="].includes(op)){take();let b=atom();if(op==="==")return a==b;if(op==="!=")return a!=b;if(op===">")return Number(a)>Number(b);if(op===">=")return Number(a)>=Number(b);if(op==="<")return Number(a)<Number(b);return Number(a)<=Number(b)}return a}function and(){let v=cmp();while(peek()==="&&"||peek()==="AND"){take();let r=cmp();v=truth(v)&&truth(r)}return v}function or(){let v=and();while(peek()==="||"||peek()==="OR"){take();let r=and();v=truth(v)||truth(r)}return v}let result=or();return p===t.length&&truth(result)}catch(e){console.warn("Invalid graph condition",src,e);return false}}

/* Full investigation state authoring and runtime extensions */

const legacyExecuteGraphEffect=executeGraphEffect;
executeGraphEffect=function(n,payload={}){ensureInvestigation();const key=n.stateKey||n.key||n.title||"unknown",value=n.value??n.text??"";switch(n.effect){case "set_variable":setInvestigationValue("variable",key,value);break;case "add_variable":changeInvestigationValue("variable",key,n.amount??(Number(value)||0));break;case "set_flag":setInvestigationValue("flag",key,n.flagValue??(value==="false"?false:true));break;case "set_relationship":setInvestigationValue("relationship",key,n.amount??value);break;case "change_relationship":changeInvestigationValue("relationship",key,n.amount??1);break;case "add_item":setInvestigationValue("item",n.itemId||key,true);break;case "remove_item":removeInvestigationItem(n.itemId||key);break;case "add_evidence":legacyExecuteGraphEffect(n,payload);addInvestigationEvidence(n.evidenceId||key,n.title||key,n.text||"");return;default:legacyExecuteGraphEffect(n,payload);return}if(opened.has("studio")&&studioTab==="state")refresh("studio");toast("Состояние расследования обновлено")};
function investigationStateView(){ensureInvestigation();const groups=[["variable","Переменные",state.investigation.variables],["flag","Флаги",state.investigation.flags],["relationship","Отношения",state.investigation.relationships]];const cards=groups.map(([type,title,obj])=>'<section class="studio-panel"><h3>'+title+'</h3>'+(Object.entries(obj).map(([k,v])=>'<div class="row-card"><span><b>'+esc(k)+'</b><br><small>'+esc(String(v))+'</small></span><button class="btn danger" data-state-delete="'+type+'" data-state-key="'+esc(k)+'">×</button></div>').join("")||'<p class="studio-help">Пока нет записей.</p>')+'</section>').join("");return '<div class="studio-grid"><section class="studio-panel"><h3>Добавить / изменить</h3><label class="studio-field">Тип<select id="state-entry-type"><option value="variable">Переменная</option><option value="flag">Флаг</option><option value="relationship">Отношение</option><option value="item">Предмет</option></select></label><label class="studio-field">Ключ или ID<input id="state-entry-key" placeholder="trust_alex / apartment_key"></label><label class="studio-field">Значение<input id="state-entry-value" placeholder="40 / true / найдено"></label><button class="btn primary" data-action="save-state-entry">Сохранить</button><h3 style="margin-top:20px">Инвентарь</h3>'+(state.investigation.inventory.map(x=>'<div class="row-card"><span>'+esc(x)+'</span><button class="btn danger" data-state-remove="'+esc(x)+'">×</button></div>').join("")||'<p class="studio-help">Инвентарь пуст.</p>')+'<h3 style="margin-top:20px">Улики</h3>'+(state.investigation.evidence.map(x=>'<div class="row-card"><span><b>'+esc(typeof x==="string"?x:x.title||x.id)+'</b><br><small>'+esc(typeof x==="string"?"":x.description||"")+'</small></span></div>').join("")||'<p class="studio-help">Улик пока нет.</p>')+'</section><section class="studio-panel"><h3>Состояние расследования</h3>'+cards+'<h3 style="margin-top:20px">История последних изменений</h3>'+(state.investigation.history.slice(0,20).map(x=>'<div class="row-card"><span>'+esc(x.type)+' · '+esc(x.key)+'<br><small>'+esc(String(x.value))+' · '+esc(x.at)+'</small></span></div>').join("")||'<p class="studio-help">Изменений пока нет.</p>')+'</section></div><p class="studio-help">Состояние сохраняется автоматически в localStorage. Отношения ограничены диапазоном от −100 до 100.</p>'}
studioView=function(){const tabs=[["os","Интерфейс ОС"],["quests","Квесты"],["dialogue","Диалоги"],["state","Состояние дела"]];const body=studioTab==="os"?studioOS():studioTab==="quests"?studioQuests():studioTab==="state"?investigationStateView():studioDialogue();return '<h2>Инструменты разработки</h2><p class="subhead">Встроенная мастерская автора · изменения сохраняются в этом браузере</p><div class="studio-tabs">'+tabs.map(([k,v])=>'<button class="studio-tab '+(studioTab===k?'active':'')+'" data-studio-tab="'+k+'">'+v+'</button>').join("")+'</div><div id="studio-body">'+body+'</div>'};
const legacyWireStudio=wireStudio;
wireStudio=function(w){legacyWireStudio(w);w.querySelectorAll("[data-studio-tab]").forEach(b=>b.onclick=()=>{studioTab=b.dataset.studioTab;refresh("studio")});if(studioTab==="state"){w.querySelectorAll("[data-state-delete]").forEach(b=>b.onclick=()=>{const type=b.dataset.stateDelete,key=b.dataset.stateKey;delete state.investigation[type==="variable"?"variables":type==="flag"?"flags":"relationships"][key];recordStateChange("delete_"+type,key,null);refresh("studio")});w.querySelectorAll("[data-state-remove]").forEach(b=>b.onclick=()=>{removeInvestigationItem(b.dataset.stateRemove);refresh("studio")})}const type=w.querySelector("#node-type");if(type){const effect=w.querySelector("#node-effect");if(effect){const opts=[["set_variable","Задать переменную"],["add_variable","Изменить переменную"],["set_flag","Установить флаг"],["set_relationship","Задать отношение"],["change_relationship","Изменить отношение"],["add_item","Добавить предмет"],["remove_item","Удалить предмет"]];opts.forEach(([v,label])=>{if(!effect.querySelector('option[value="'+v+'"]'))effect.add(new Option(label,v))});const n=state.nodes.find(x=>x.id===selectedNode);if(n)effect.value=n.effect||"send_message";if(!w.querySelector("#state-node-fields")){const box=document.createElement("div");box.id="state-node-fields";box.innerHTML='<label class="studio-field">Ключ / ID<input id="node-state-key"></label><label class="studio-field">Значение<input id="node-state-value"></label><label class="studio-field">Изменение на<input id="node-state-amount" type="number" value="1"></label><label class="studio-field">ID предмета<input id="node-item-id"></label>';effect.closest(".studio-field").after(box)}const fill=()=>{const n=state.nodes.find(x=>x.id===selectedNode),v=effect.value,box=w.querySelector("#state-node-fields");box.style.display=["set_variable","add_variable","set_flag","set_relationship","change_relationship","add_item","remove_item"].includes(v)?"block":"none";w.querySelector("#node-state-key").value=n?.stateKey||n?.key||"";w.querySelector("#node-state-value").value=n?.value??"";w.querySelector("#node-state-amount").value=n?.amount??1;w.querySelector("#node-item-id").value=n?.itemId||""};fill();effect.onchange=fill}const cond=w.querySelector("#node-condition");if(cond&&cond.tagName==="SELECT"){const area=document.createElement("textarea");area.id="node-condition";area.className="studio-field";area.value=state.nodes.find(x=>x.id===selectedNode)?.condition||"has_evidence";area.placeholder='flag("found_photo") AND rel("alex") >= 50';cond.replaceWith(area);area.style.minHeight="80px"}}};
const legacyStudioAction=studioAction;
studioAction=function(action,w,e){const n=state.nodes.find(x=>x.id===selectedNode);if(action==="save-node"&&n){n.stateKey=w.querySelector("#node-state-key")?.value||n.stateKey||"";n.key=n.stateKey;n.value=w.querySelector("#node-state-value")?.value??n.value??"";n.amount=Number(w.querySelector("#node-state-amount")?.value??n.amount??1);n.itemId=w.querySelector("#node-item-id")?.value||n.itemId||""}if(action==="save-state-entry"){const type=w.querySelector("#state-entry-type").value,key=w.querySelector("#state-entry-key").value,raw=w.querySelector("#state-entry-value").value;let val=raw;if(raw==="true"||raw==="false")val=raw==="true";else if(raw.trim()!==""&&Number.isFinite(Number(raw)))val=Number(raw);if(type==="item")setInvestigationValue("item",key,true);else setInvestigationValue(type,key,val);refresh("studio");return}legacyStudioAction(action,w,e)};

/* Conditional choice visibility */

const previousShowGraphChoice=showGraphChoice;
showGraphChoice=function(n,payload,depth){const available=(n.outputs||[]).map((o,i)=>({o,i})).filter(x=>!x.o.condition||evaluateGraphCondition(x.o.condition));const temp={...n,outputs:available.map(x=>x.o)};const original=state.nodes.find(x=>x.id===n.id);if(original){const remap=new Map(available.map((x,i)=>[i,x.i]));$("#story-choice")?.remove();activeGraphRun={nodeId:n.id,payload,depth};const box=document.createElement("div");box.id="story-choice";box.className="story-choice-overlay";box.innerHTML='<section class="story-choice-card"><div class="call-kicker">ВЫБОР</div><h2>'+esc(n.title||"Твой ответ")+'</h2><p>'+esc(n.text||"Как поступить?")+'</p><div class="story-choice-options">'+available.map(({o,i})=>'<button class="btn primary" data-choice-index="'+i+'">'+esc(o.label||("Вариант "+(i+1)))+'</button>').join("")+'</div></section>';if(!available.length)box.querySelector(".story-choice-options").textContent="Сейчас нет доступных вариантов.";$("#desktop").append(box);box.querySelectorAll("[data-choice-index]").forEach(b=>b.onclick=()=>{const visibleIndex=Number(b.dataset.choiceIndex),actualIndex=remap.get(visibleIndex),target=original.outputs?.[actualIndex]?.target;box.remove();activeGraphRun=null;if(target)runGraphFrom(target,payload,depth+1);else toast("У выбранного ответа нет продолжения")})}else previousShowGraphChoice(n,payload,depth)};
const previousWireStudio=wireStudio;
wireStudio=function(w){previousWireStudio(w);const n=state.nodes.find(x=>x.id===selectedNode);if(n?.type==="choice"){w.querySelectorAll("[data-branch-label]").forEach(input=>{const i=Number(input.dataset.branchLabel),row=input.closest(".branch-row");if(!row||row.querySelector("[data-branch-condition]"))return;const field=document.createElement("input");field.dataset.branchCondition=String(i);field.placeholder="Условие доступности (необязательно)";field.value=n.outputs?.[i]?.condition||"";field.title='Например: flag("found_key") AND rel("alex") >= 30';row.insertBefore(field,row.querySelector("span"))})}};
const previousStudioAction=studioAction;
studioAction=function(action,w,e){if(action==="save-branches"){const n=state.nodes.find(x=>x.id===selectedNode);if(n)w.querySelectorAll("[data-branch-condition]").forEach(input=>{const o=n.outputs[Number(input.dataset.branchCondition)];if(o)o.condition=input.value.trim()})}previousStudioAction(action,w,e)};
